-- A record's history: the changes of the underway convoy's status in Anvil, the same statement keeping one field's records (?field=statusId, named in the change set by its Go field name): one range of the table's key, each record's change set read to keep it.
SELECT EventTime, Sequence, Operation, TO_JSON_STRING(ChangeSet) AS ChangeSet, Auth, ActorUserId, ActorUsername, PrincipalUserId, PrincipalUsername, PrincipalRole, SessionId, Process, Rpc FROM DataChangeEvents WHERE TableName = 'Missions' AND RowId = '80000000-0000-4000-8000-000000000003' AND TenantId = 'a1111111-1111-4111-8111-111111111111' AND JSON_QUERY(ChangeSet, '$.StatusID') IS NOT NULL ORDER BY EventTime DESC, Sequence DESC LIMIT 51
